args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?husband ?husbandLabel ?placeIRI ?placeIRIlabel ?placeLiteral WHERE {
  dbr:Sirikit dbo:spouse ?husband .
  OPTIONAL { ?husband dbo:deathPlace ?placeIRI .
             OPTIONAL { ?placeIRI rdfs:label ?placeIRIlabel FILTER(langMatches(lang(?placeIRIlabel), "en")) }
  }
  OPTIONAL { ?husband dbp:deathPlace ?placeLiteral . FILTER(langMatches(lang(?placeLiteral), "en")) }
  OPTIONAL { ?husband rdfs:label ?husbandLabel FILTER(langMatches(lang(?husbandLabel), "en")) }
} LIMIT 50

